260	     * Reads the {@code Idempotency-Key} header of the request currently being handled, used to make
261	     * owner creation idempotent. Returns the trimmed key when present and non-blank, otherwise
262	     * {@code null} (including when there is no active servlet request), so a missing or blank key
263	     * simply means "no idempotency" and the create proceeds normally.
264	     *
265	     * @return the current request's idempotency key, or {@code null} when none is supplied
266	     */
267	    private static String currentIdempotencyKey() {
268	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
269	        if (!(attributes instanceof ServletRequestAttributes servletAttributes)) {
270	            return null;
271	        }
272	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
273	        if (key == null || key.isBlank()) {
274	            return null;
275	        }
276	        return key.trim();
277	    }
