720	    /**
721	     * Populates an owner's {@code membershipPoints} and {@code membershipLevel} on the given
722	     * dto using a pre-computed map of household id to member count.
723	     *
724	     * @param ownerDto       the dto to populate
725	     * @param owner          the owner being mapped
726	     * @param householdSizes household id to member count, as returned by {@link #householdSizes()}
727	     */
728	    private void applyMembership(OwnerDto ownerDto, Owner owner, Map<String, Integer> householdSizes) {
729	        int householdSize = owner.getHouseholdId() == null ? 1
730	            : householdSizes.getOrDefault(owner.getHouseholdId(), 1);
731	        int points = MembershipPoints.points(owner, householdSize);
732	        ownerDto.setMembershipPoints(points);
733	        ownerDto.setMembershipLevel(MembershipPoints.level(points));
734	    }
