736	    /**
737	     * Caps a newly created owner's {@code membershipLevel} at one above the highest
738	     * {@code membershipLevel} among the other current members of its household, writing the
739	     * capped value back onto the dto and returning it. A member's current level is scored the
740	     * same way as {@link #applyMembership}, using {@code householdSizes} so the
741	     * household-of-three-or-more factor reflects the household as it now stands. When the owner
742	     * has no household, or is the only member of its household, no cap applies and the level is
743	     * returned unchanged.
744	     *
745	     * @param ownerDto       the newly created owner's dto, with its uncapped membership already applied
746	     * @param owner          the newly created owner (already saved, so it has an id)
747	     * @param householdSizes household id to member count, as returned by {@link #householdSizes()}
748	     * @return the resulting (possibly capped) membership level
749	     */
750	    private int capMembershipLevelToHousehold(OwnerDto ownerDto, Owner owner,
751	        Map<String, Integer> householdSizes) {
752	        int level = ownerDto.getMembershipLevel();
753	        String householdId = owner.getHouseholdId();
754	        if (householdId == null) {
755	            return level;
756	        }
757	        Integer maxMemberLevel = null;
758	        for (Owner existing : this.clinicService.findAllOwners()) {
759	            if (existing.isDeleted() || existing.getId().equals(owner.getId())) {
760	                continue;
761	            }
762	            if (householdId.equals(existing.getHouseholdId())) {
763	                int size = householdSizes.getOrDefault(householdId, 1);
764	                int memberLevel = MembershipPoints.level(MembershipPoints.points(existing, size));
765	                maxMemberLevel = maxMemberLevel == null ? memberLevel
766	                    : Math.max(maxMemberLevel, memberLevel);
767	            }
768	        }
769	        if (maxMemberLevel != null && level > maxMemberLevel + 1) {
770	            level = maxMemberLevel + 1;
771	            ownerDto.setMembershipLevel(level);
772	        }
773	        return level;
774	    }
