777	     * Counts how many owners belong to each household, keyed by household id. Owners without a
778	     * household id (no postcode) are excluded — such an owner is its own single-member household.
779	     *
780	     * @return a map from household id to the number of owners sharing it
781	     */
782	    private Map<String, Integer> householdSizes() {
783	        Map<String, Integer> sizes = new java.util.HashMap<>();
784	        for (Owner existing : this.clinicService.findAllOwners()) {
785	            String householdId = existing.getHouseholdId();
