793	    /**
794	     * Applies soft-match (possible-duplicate) detection to a new owner that has already
795	     * cleared hard {@code identityKey} duplicate rejection. The owner is flagged as a
796	     * possible duplicate when an existing owner shares its last name (compared
797	     * case-insensitively with collapsed whitespace) and its postcode while having a
798	     * different normalized telephone; {@code possibleDuplicateOf} is then set to that
799	     * existing owner's id. When several existing owners match, the one with the lowest id
800	     * is chosen so the result is deterministic. When no such owner exists — or the new
801	     * owner has no postcode to compare — {@code possibleDuplicate} is set to {@code false}
802	     * and no matching id is recorded.
803	     *
804	     * @param owner the new owner, already normalized (E.164 telephone, validated postcode)
805	     */
806	    private void applyPossibleDuplicate(Owner owner) {
807	        owner.setPossibleDuplicate(false);
808	        if (owner.getPostcode() == null) {
809	            return;
810	        }
811	        String lastNameKey = householdKey(owner.getLastName());
812	        Owner match = null;
813	        for (Owner existing : this.clinicService.findAllOwners()) {
814	            if (lastNameKey.equals(householdKey(existing.getLastName()))
815	                && owner.getPostcode().equals(existing.getPostcode())
816	                && !owner.getTelephone().equals(toE164(existing.getTelephone()))) {
817	                if (match == null || (existing.getId() != null
818	                    && existing.getId() < match.getId())) {
819	                    match = existing;
820	                }
821	            }
822	        }
823	        if (match != null) {
824	            owner.setPossibleDuplicate(true);
825	            owner.setPossibleDuplicateOf(match.getId());
826	        }
827	    }
