839	     * @param householdId         the shared household id, or {@code null} when the owner is not in a household
840	     * @return the identity key string
841	     */
842	    private static String identityKey(String normalizedTelephone, String email, String householdId) {
843	        return (normalizedTelephone == null ? "" : normalizedTelephone)
844	            + "|" + (email == null ? "" : email)
845	            + "|" + (householdId == null ? "" : householdId);
