860	    /**
861	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes
862	     * and brackets are stripped. When the number already carries a leading {@code '+'}
863	     * and country code these are kept; a number written in national trunk form (a leading
864	     * {@code '0'}) is treated as Australian, so the {@code '0'} is dropped and country code
865	     * {@code '+61'} prepended; any other bare number is treated as a NANP number and country
866	     * code {@code '+1'} is prepended. The resulting number must have between 8 and 15 digits
867	     * after the {@code '+'}, and its national-number length must be valid for the detected
868	     * country code (see {@link #hasValidNationalLength}).
869	     *
870	     * @param telephone the raw telephone value supplied by the client
871	     * @return the E.164 telephone (e.g. {@code +61412345678}), or {@code null} when it
872	     *         cannot form a valid E.164 number (signalling a 400 Bad Request)
873	     */
874	    private static String toE164(String telephone) {
875	        if (telephone == null) {
876	            return null;
877	        }
878	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
879	        String digits;
880	        if (cleaned.startsWith("+")) {
881	            digits = cleaned.substring(1);
882	        } else if (cleaned.startsWith("0")) {
883	            digits = "61" + cleaned.substring(1);
884	        } else {
885	            digits = "1" + cleaned;
886	        }
887	        if (!digits.matches("[0-9]{8,15}")) {
888	            return null;
889	        }
890	        if (!hasValidNationalLength(digits)) {
891	            return null;
892	        }
893	        return "+" + digits;
894	    }
895	
896	    /**
897	     * Validates the national-number length of an E.164 digit string against its country
898	     * code: Australia ({@code +61}) requires exactly 9 national digits and the NANP
899	     * ({@code +1}) requires exactly 10. Numbers under any other country code are not
900	     * length-checked here — only the general 8-to-15-digit E.164 bound applies to them.
901	     *
902	     * @param digits the E.164 digits (without the leading {@code '+'})
903	     * @return {@code true} when the national-number length is valid for the country code
904	     */
905	    private static boolean hasValidNationalLength(String digits) {
906	        if (digits.startsWith("61")) {
907	            return digits.length() - 2 == 9;
908	        }
909	        if (digits.startsWith("1")) {
910	            return digits.length() - 1 == 10;
911	        }
912	        return true;
913	    }
