915	    /**
916	     * Inclusive 4-digit postcode ranges permitted for each canonical region: NSW 2000-2099,
917	     * VIC 3000-3099 and QLD 4000-4099. A region absent from this table (e.g. the {@code
918	     * "UNKNOWN"} derived for a city with no known region) imposes no range restriction.
919	     */
920	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
921	        "NSW", new int[] {2000, 2099},
922	        "VIC", new int[] {3000, 3099},
923	        "QLD", new int[] {4000, 4099});
924	
925	    /**
926	     * Validates an owner's postcode for creation. A postcode is only ever validated when
927	     * present (an absent postcode is optional and accepted). When present it must be exactly
928	     * four digits and, for a city whose {@link OwnerLocality#forCity region} has a known
929	     * postcode range, must fall inside that inclusive range (NSW 2000-2099, VIC 3000-3099,
930	     * QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
931	     *
932	     * @param postcode the supplied postcode (never {@code null} here)
933	     * @param city     the owner's city, used to derive the region
934	     * @return {@code true} when the postcode is valid for the city, {@code false} otherwise
935	     *         (signalling a 400 Bad Request)
936	     */
937	    private static boolean isValidPostcode(String postcode, String city) {
938	        if (!postcode.matches("[0-9]{4}")) {
939	            return false;
940	        }
941	        int[] range = REGION_POSTCODES.get(
942	            org.springframework.samples.petclinic.mapper.OwnerLocality.forCity(city));
943	        if (range == null) {
944	            return true;
945	        }
946	        int value = Integer.parseInt(postcode);
947	        return value >= range[0] && value <= range[1];
948	    }
