950	    /**
951	     * Disposable email domains that are not accepted for owner creation. An owner whose
952	     * email domain (compared case-insensitively) is in this set is rejected with a 400
953	     * Bad Request.
954	     */
955	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
956	        "mailinator.com", "tempmail.com", "guerrillamail.com");
957	
958	    /**
959	     * Normalizes an owner email for creation. A present email must be a syntactically
960	     * valid address whose domain is not on the disposable-domain blocklist ({@link
961	     * #DISPOSABLE_EMAIL_DOMAINS}); the returned value is lower-cased.
962	     *
963	     * @param email the raw email value supplied by the client (never {@code null} here)
964	     * @return the lower-cased email, or {@code null} when it is not a syntactically valid
965	     *         address or its domain is a disposable domain (signalling a 400 Bad Request)
966	     */
967	    private static String normalizeEmail(String email) {
968	        String trimmed = email.trim();
969	        if (!trimmed.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")) {
970	            return null;
971	        }
972	        String normalized = trimmed.toLowerCase();
973	        String domain = normalized.substring(normalized.indexOf('@') + 1);
974	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
975	            return null;
976	        }
977	        return normalized;
978	    }
